const r=await tools.exec_command({cmd:"cat >> src/server_update.mbt <<'EOF'

///|
async fn update_one_server(state : Json, provider : String, version : String, force : Bool) -> Json {
  let directory = required(state, "tunnelDirectory")
  let result : Json = {
    "id": required(state, "workspaceId"),
    "provider": provider,
    "context": required(state, "context"),
    "targetVersion": version,
    "outcome": "failed",
  }
  let mut phase = "identity"
  try {
    let operation = connection_operation_lock(state)
    defer operation.close()
    let current = workspace(state)
    guard current is Some(current) &&
      field(current, "uid") == field(state, "workspaceUid") &&
      field(field(current, "provider").unwrap_or(Json::null()), "name") == Some(Json::string(provider)) else {
      raise AdapterError("Workspace is missing, replaced, or has a different provider")
    }
    phase = "workspace-status"
    let status = workspace_status(state)
    set_field(result, "workspaceStatus", Json::string(status))
    if status == "Stopped" {
      set_field(result, "outcome", Json::string("skipped"))
      set_field(result, "reason", Json::string("workspace_stopped"))
      save_diagnostic("server-update", "skipped", evidence=result, tunnel_directory=directory)
      return result
    }
    guard status == "Running" else { raise AdapterError("Workspace is not running") }
    phase = "transport"
    ensure_ssh_worker(state, Some(reserve_server_port(state)))
    let lock = @fs.open(directory + "/server.lock", mode=ReadWrite, create_mode=OpenOrCreate, permission=0o600)
    defer lock.close()
    @async.with_timeout(30000, async fn() {
      while !lock.try_lock(Exclusive) { @async.sleep(100) }
    })
    let pending = @fs.exists(directory + "/server-update-pending")
    set_field(result, "retry", Json::boolean(pending))
    phase = "version"
    let installed = remote(state,
      "base=\"$HOME/.local/share/orca-env-devsy/orca\"; dir=\"$base/current\"; if test ! -x \"$dir/orca-ide\"; then dir=\"$base/update-previous\"; fi; ELECTRON_RUN_AS_NODE=1 \"$dir/orca-ide\" \"$dir/resources/app.asar/out/cli/index.js\" --version",
      "server-update-version").trim().to_owned()
    ignore(server_version(installed))
    set_field(result, "previousVersion", Json::string(installed))
    if server_version_is_older(version, installed) && !force {
      raise AdapterError("Server downgrade requires --force")
    }
    if !pending && installed == version && server_is_running(state) {
      set_field(result, "outcome", Json::string("success"))
      set_field(result, "reason", Json::string("already_current"))
      save_diagnostic("server-update", "success", evidence=result, tunnel_directory=directory)
      return result
    }
    phase = "prepare"
    if !pending {
      ignore(remote(state, "test ! -e \"$HOME/.local/share/orca-env-devsy/orca/update-previous\" && test ! -e \"$HOME/.local/share/orca-env-devsy/orca/update-retry\"", "server-update-ownership"))
    }
    ignore(remote(state, server_update_prepare_script(version), "server-update-prepare"))
    phase = "identity-recheck"
    let current = workspace(state)
    guard current is Some(current) && field(current, "uid") == field(state, "workspaceUid") &&
      field(field(current, "provider").unwrap_or(Json::null()), "name") == Some(Json::string(provider)) &&
      workspace_status(state) == "Running" else {
      raise AdapterError("Workspace changed before Server update")
    }
    @fs.write_file(directory + "/server-update-pending", version, permission=0o600)
    phase = "stop"
    ignore(remote(state, server_update_stop_script(required(state, "projectRoot")), "server-update-stop"))
    phase = "switch"
    ignore(remote(state, server_update_swap_script(version), "server-update-switch"))
    phase = "start"
    ignore(launch_server(state))
    phase = "verify"
    let actual = remote(state,
      "base=\"$HOME/.local/share/orca-env-devsy/orca/current\"; ELECTRON_RUN_AS_NODE=1 \"$base/orca-ide\" \"$base/resources/app.asar/out/cli/index.js\" --version",
      "server-update-verify-version").trim().to_owned()
    guard actual == version else { raise AdapterError("Updated Server version does not match Desktop") }
    @async.with_timeout(15000, async fn() {
      while !server_is_running(state) { @async.sleep(200) }
    })
    phase = "cleanup"
    ignore(remote(state, "base=\"$HOME/.local/share/orca-env-devsy/orca\"; rm -rf \"$base/update-previous\" \"$base/update-retry\"", "server-update-cleanup"))
    @fs.remove(directory + "/server-update-pending")
    set_field(result, "outcome", Json::string("success"))
    save_diagnostic("server-update", "success", evidence=result, tunnel_directory=directory)
  } catch {
    error => {
      set_field(result, "phase", Json::string(phase))
      set_field(result, "error", Json::string(redact_credentials(error.to_string())))
      set_field(result, "recoverySuppressed", Json::boolean(@fs.exists(directory + "/server-update-pending")))
      save_diagnostic("server-update", "failed", phase~, error_type="server_update_failed", evidence=result, tunnel_directory=directory)
    }
  }
  result
}

///|
pub async fn update_server(args : Array[String]) -> Unit {
  let options = server_update_options(args)
  let version = desktop_orca_version()
  let base = adapter_state_home() + "/tunnels"
  let states : Array[Json] = []
  let errors : Array[Json] = []
  let results : Array[Json] = []
  save_diagnostic("server-update-batch", "started", evidence={
    "provider": options.provider.map(Json::string).unwrap_or(Json::null()),
    "workspace": options.workspace.map(Json::string).unwrap_or(Json::null()),
    "force": options.force,
    "targetVersion": version,
  })
  if @fs.exists(base) {
    for name in @fs.readdir(base, sort=true) {
      let directory = base + "/" + name
      try {
        if @fs.kind(directory, follow_symlink=false) != @fs.FileKind::Directory || !@fs.exists(directory + "/enabled") { continue }
        let state = @json.parse(@fs.read_file(directory + "/state.json").text())
        validate_state(state)
        if field(state, "connection") != Some(Json::string("orca-server")) { continue }
        if options.workspace is Some(id) && field(state, "workspaceId") != Some(Json::string(id)) { continue }
        ignore(required(state, "workspaceUid"))
        ignore(required(state, "context"))
        set_field(state, "tunnelDirectory", Json::string(directory))
        states.push(state)
      } catch {
        error => errors.push({ "savedState": directory, "error": redact_credentials(error.to_string()) })
      }
    }
  }
  let keys : Map[String, Int32] = Map([])
  for state in states {
    let key = required(state, "context") + ":" + required(state, "workspaceUid")
    keys.set(key, keys.get(key).unwrap_or(0) + 1)
  }
  for state in states {
    try {
      let key = required(state, "context") + ":" + required(state, "workspaceUid")
      guard keys.get(key) == Some(1) else { raise AdapterError("Duplicate saved workspace identity") }
      let current = workspace(state)
      guard current is Some(current) else { raise AdapterError("Workspace is missing") }
      let provider = required(field(current, "provider").unwrap_or(Json::null()), "name")
      if options.provider is Some(filter) && provider != filter { continue }
      results.push(update_one_server(state, provider, version, options.force))
    } catch {
      error => errors.push({ "workspace": required(state, "workspaceId"), "error": redact_credentials(error.to_string()) })
    }
  }
  if options.workspace is Some(_) && results.is_empty() && errors.is_empty() {
    errors.push({ "error": "Workspace not found for provider" })
  }
  let failed = results.filter(row => field(row, "outcome") == Some(Json::string("failed"))).length() + errors.length()
  let output : Json = {
    "schemaVersion": 1,
    "action": "update-server",
    "targetVersion": version,
    "workspaces": results,
    "errors": errors,
    "failed": failed,
